import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import SectionCard from "./SectionCard";
import DashboardCard from "./DashboardCard";
import { FaBell, FaCheckCircle, FaEnvelopeOpen } from "react-icons/fa";
import "./dashboard.css";

function ReminderPanel() {
  const userId = localStorage.getItem("user_id");

  const [reminders, setReminders] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadReminders = async () => {
    try {
      setLoading(true);
      const res = await axios.get(
        `http://127.0.0.1:8000/reminders/${userId}`
      );
      setReminders(res.data.reminders || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadReminders();
  }, []);

  const markRead = async (id) => {
    try {
      await axios.put(
        `http://127.0.0.1:8000/reminders/read/${id}`
      );
      loadReminders();
    } catch (err) {
      console.error(err);
    }
  };

  const unreadCount = reminders.filter((r) => r.is_read === 0).length;

  return (
    <div>
      <PageHeader
        title="Reminders & Notifications"
        subtitle="Stay updated with your daily study alerts and tasks."
      />

      {/* STATS */}
      <div className="grid-3" style={{ marginBottom: "20px" }}>
        <DashboardCard
          icon={<FaBell />}
          label="Total Reminders"
          value={reminders.length}
        />

        <DashboardCard
          icon={<FaEnvelopeOpen />}
          label="Unread"
          value={unreadCount}
        />

        <DashboardCard
          icon={<FaCheckCircle />}
          label="Read"
          value={reminders.length - unreadCount}
        />
      </div>

      {/* REMINDER LIST */}
      <SectionCard title="Reminder Feed">
        {loading ? (
          <p>Loading...</p>
        ) : reminders.length === 0 ? (
          <p>No reminders found.</p>
        ) : (
          reminders.map((r) => (
            <div className="list-card" key={r.id}>
              <h4 style={{ marginTop: 0 }}>{r.message}</h4>

              <div className="meta">
                Date: {r.reminder_date}
              </div>

              <div style={{ marginTop: "10px" }}>
                <span
                  className={
                    r.is_read === 1
                      ? "badge badge-green"
                      : "badge badge-orange"
                  }
                >
                  {r.is_read === 1 ? "Read" : "Unread"}
                </span>
              </div>

              {r.is_read === 0 && (
                <div style={{ marginTop: "12px" }}>
                  <button
                    className="btn btn-primary"
                    onClick={() => markRead(r.id)}
                  >
                    Mark as Read
                  </button>
                </div>
              )}
            </div>
          ))
        )}
      </SectionCard>
    </div>
  );
}

export default ReminderPanel;
